pub fn printSkippedPackages(skipped_packages: std.array_list.Managed(string)) void {
        if ((skipped_packages.items.len > 0)) {
            _ = Output.pretty("<d>Skipped<r> ", .{});
            var i: usize = 0;
            _ = &i;
            for (skipped_packages.items) |package_name| {
                _ = &package_name;
                if ((i > 0)) {
                    _ = Output.pretty(", ", .{});
                }
                i = (i + 1);
                _ = Output.pretty("{s}", .{ package_name });
            }
            if ((skipped_packages.items.len > 1)) {
                _ = Output.prettyln(" <d>because they do not come from the default registry<r>", .{});
            } else {
                _ = Output.prettyln(" <d>because it does not come from the default registry<r>", .{});
            }
            _ = Output.prettyln("", .{});
        }
}

